from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v != 0}, key=lambda c: min((r, col) for r in range(h) for col in range(w) if grid[r][col] == c)[1])
    objects = []
    for color in colors:
        cells = {(r, col) for r in range(h) for col in range(w) if grid[r][col] == color}
        # Each color forms a single object; preserve its exact shape.
        r0 = min(r for r, _ in cells); r1 = max(r for r, _ in cells)
        c0 = min(col for _, col in cells); c1 = max(col for _, col in cells)
        mask = {(r-r0, col-c0) for r, col in cells}
        objects.append((color, r1-r0+1, c1-c0+1, mask))
    out = [[0]*w for _ in range(h)]
    r0 = c0 = 0
    for i, (color, oh, ow, mask) in enumerate(objects):
        for dr, dc in mask:
            if 0 <= r0+dr < h and 0 <= c0+dc < w:
                out[r0+dr][c0+dc] = color
        r0 += oh-1
        c0 += ow-1
    return out
